"""Moves sub work items onto the style + parent category model.

Imported sub work items kept their style id (the sheet's SKU) in OrderDetail.category.
For every live sub work item this:
  * sets its style from that category value, reusing the workspace's style with the same
    code (ignoring case) or creating one; sub-items that already have a style keep it,
  * then copies the parent's fit and category onto it, as new sub-items get at creation,
  * and puts each newly-styled style under the fit its parents use most, if that fit is in
    the product master and the style isn't under a fit yet.

Values that aren't style ids are skipped: blanks, placeholders such as "TBD", and values that
are a category (the parent's, or any category in the product master), which is what sub-items
created from the app already hold.
"""

from collections import Counter, defaultdict

from django.db import migrations
from django.db.models import F

PLACEHOLDER_CODES = {"tbd", "tba", "na", "n/a", "none", "-", "--"}
STYLE_CODE_MAX_LENGTH = 100


def _key(value):
    return (value or "").strip().lower()


def plan_sub_item_backfill(sub_items, parent_values, existing_styles, category_names, fit_ids):
    """Works out the backfill without touching the database.

    sub_items: dicts with id, workspace_id, parent_id, category, fit, style_id
    parent_values: {parent issue id: (fit, category)} for parents that have order details
    existing_styles: {(workspace_id, lowercased code): (style id, fit id or None)}
    category_names: {(workspace_id, lowercased category name)} from the product master
    fit_ids: {(workspace_id, lowercased category, lowercased fit): fit id}

    Returns (updates, new_styles, style_fits):
      updates: {sub item id: {"style_key": (workspace_id, code) or None, "fit": str, "category": str}};
        style_key None means the style is left as it is
      new_styles: {(workspace_id, lowercased code): code as first written}
      style_fits: {(workspace_id, lowercased code): fit id} for styles to put under a fit
    """
    updates = {}
    new_styles = {}
    fit_votes = defaultdict(Counter)

    for item in sub_items:
        workspace_id = item["workspace_id"]
        parent = parent_values.get(item["parent_id"])
        # without parent order details there's nothing to copy, so fit/category stay as they are
        fit, category = parent if parent is not None else (item["fit"], item["category"])
        parent_category = _key(parent[1]) if parent is not None else None

        style_key = None
        code = (item["category"] or "").strip()
        if (
            item["style_id"] is None
            and code
            and len(code) <= STYLE_CODE_MAX_LENGTH
            and code.lower() not in PLACEHOLDER_CODES
            and code.lower() != parent_category
            and (workspace_id, code.lower()) not in category_names
        ):
            style_key = (workspace_id, code.lower())
            if style_key not in existing_styles:
                new_styles.setdefault(style_key, code)
            fit_id = fit_ids.get((workspace_id, _key(category), _key(fit)))
            if fit_id:
                fit_votes[style_key][fit_id] += 1

        if style_key is None and fit == item["fit"] and category == item["category"]:
            continue
        updates[item["id"]] = {"style_key": style_key, "fit": fit, "category": category}

    style_fits = {}
    for style_key, votes in fit_votes.items():
        existing = existing_styles.get(style_key)
        if existing is not None and existing[1] is not None:
            continue
        style_fits[style_key] = votes.most_common(1)[0][0]

    return updates, new_styles, style_fits


